<template><view class="page" v-if="car"><swiper class="swiper"><swiper-item v-for="(img,i) in car.images" :key="i"><image :src="img" mode="aspectFill"/></swiper-item></swiper><view class="card"><view class="h">{{car.brand}} {{car.series}}</view><view class="muted">{{car.year}}年 · {{car.mileage}}万公里 · {{car.color}}</view><view class="price">¥{{car.price}}</view><view>{{car.condition}}</view></view><view class="card"><view class="h">分期/以租代购方案</view><view v-for="(p,i) in car.plans" :key="i" class="plan">首付 ¥{{p.downPayment}} · 月供 ¥{{p.monthlyPayment}} · {{p.term}}期 · 保证金 ¥{{p.deposit}}<text class="muted">（{{p.method==='principal'?'等额本金':'等额本息'}}，具体以合同为准）</text></view></view><view class="card"><view class="h">预约看车 / 留资</view><input v-model="form.name" placeholder="姓名（选填）"/><input v-model="form.phone" type="number" placeholder="手机号"/><button class="btn" @click="submit">提交后我们会尽快联系您</button><navigator url="/pages/privacy/privacy" class="privacy">隐私协议</navigator></view></view></template>
<script setup>import {ref} from 'vue';const car=ref(null),form=ref({name:'',phone:''});const id=ref('');const db=wx.cloud.database();onLoad(async o=>{id.value=o.id;car.value=(await db.collection('vehicles').doc(o.id).get()).data});async function submit(){if(!/^1\d{10}$/.test(form.value.phone))return uni.showToast({title:'请输入正确手机号',icon:'none'});await db.collection('leads').add({data:{...form.value,vehicleId:id.value,createdAt:db.serverDate()}});uni.showToast({title:'提交成功'});form.value={name:'',phone:''}}</script>
<style scoped>.swiper,.swiper image{width:100%;height:460rpx}.h{font-size:32rpx;font-weight:600;margin-bottom:14rpx}.price{font-size:40rpx;color:#ef4444;margin:14rpx 0}.plan{padding:18rpx 0;border-bottom:1px solid #eee}.plan:last-child{border:0}input{background:#f5f6f8;padding:20rpx;margin:12rpx 0;border-radius:8rpx}.privacy{display:block;text-align:center;color:#1677ff;margin-top:20rpx}</style>
